import * as THREE from 'three';

/**
 * The fidāʾī as generated by Tripo (scripts/build-hero.mjs): a skinned GLB with
 * idle and walk clips, listed in `assets/characters/manifest.json`:
 *
 *   { "player": { "file": "fidai/fidai.glb", "height": 1.78, "yaw": 0, "walkSpeed": 1.5 } }
 *
 * The generated character has no aiming, crouching, fighting, riding or dying
 * animations, so the game shows it while the player is simply standing or
 * walking about and switches to the procedural rig for everything else.
 * Missing manifest or file: the procedural fidāʾī only, as before.
 */
type Entry = { file: string; height?: number; yaw?: number; walkSpeed?: number };

const BASE = 'assets/characters/';
const DOWN_Y = new THREE.Vector3(0, -1, 0);
/** a slung long gun: lying across the back, muzzle up over the left shoulder */
const BACK = new THREE.Euler(0, 0, Math.PI - 0.75);

export class HeroModel {
  readonly root = new THREE.Group();
  private readonly mixer: THREE.AnimationMixer;
  private readonly idle: THREE.AnimationAction | null;
  private readonly walk: THREE.AnimationAction | null;
  private walking = false;
  private readonly walkSpeed: number;
  private readonly bones = new Map<string, THREE.Object3D>();
  /** the weapon he carries (a copy of the rig's), in his right hand or slung on his back */
  private held: THREE.Object3D | null = null;
  private heldHow: 'hand' | 'back' = 'hand';
  private readonly a = new THREE.Vector3();
  private readonly b = new THREE.Vector3();
  private readonly q = new THREE.Quaternion();
  private readonly q2 = new THREE.Quaternion();

  private constructor(scene: THREE.Object3D, clips: THREE.AnimationClip[], entry: Entry) {
    this.root.name = 'hero';
    this.walkSpeed = entry.walkSpeed ?? 1.5;
    // stand it up at the game's scale, feet on the ground, facing the way the player faces (+z)
    const turn = new THREE.Group();
    turn.add(scene);
    const box = new THREE.Box3().setFromObject(scene);
    const size = box.getSize(new THREE.Vector3());
    scene.scale.multiplyScalar((entry.height ?? 1.78) / Math.max(1e-3, size.y));
    scene.position.y = -box.min.y * scene.scale.y;
    // a T-pose with the arms along z faces along x: turn it a quarter round unless told otherwise
    turn.rotation.y = THREE.MathUtils.degToRad(entry.yaw ?? (size.x < size.z ? -90 : 0));
    this.root.add(turn);
    scene.traverse((o) => {
      if ((o as THREE.Bone).isBone) this.bones.set(o.name, o);
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.castShadow = true;
      m.receiveShadow = true;
      // one character: skip culling against a bind-pose bounding sphere
      m.frustumCulled = false;
    });
    this.mixer = new THREE.AnimationMixer(scene);
    const find = (key: string) => clips.find((c) => c.name.toLowerCase().includes(key)) ?? null;
    const idle = find('idle');
    const walk = find('walk');
    this.idle = idle ? this.mixer.clipAction(idle) : null;
    this.walk = walk ? this.mixer.clipAction(walk) : null;
    this.idle?.play();
    if (this.walk) {
      this.walk.play();
      this.walk.setEffectiveWeight(0);
    }
    this.root.visible = false;
  }

  /** The hero listed in the manifest, or null (no manifest, no entry, unreadable file). */
  static async load(): Promise<HeroModel | null> {
    try {
      const res = await fetch(`${BASE}manifest.json`, { cache: 'no-cache' });
      if (!res.ok || !(res.headers.get('content-type') ?? '').includes('json')) return null;
      const entry = ((await res.json()) as { player?: Entry }).player;
      if (!entry?.file) return null;
      const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
      const gltf = await new GLTFLoader().loadAsync(BASE + entry.file);
      return new HeroModel(gltf.scene, gltf.animations, entry);
    } catch {
      return null;
    }
  }

  get clips(): string[] {
    return [this.idle, this.walk].flatMap((a) => (a ? [a.getClip().name] : []));
  }

  /** Follow the player; idle when standing, a walk whose cadence follows the ground speed. */
  update(dt: number, pos: THREE.Vector3, yaw: number, speed: number, show: boolean): void {
    this.root.visible = show;
    if (!show) return;
    this.root.position.copy(pos);
    this.root.rotation.y = yaw;
    const walking = speed > 0.25;
    if (walking !== this.walking && this.idle && this.walk) {
      this.walking = walking;
      const from = walking ? this.idle : this.walk;
      const to = walking ? this.walk : this.idle;
      to.enabled = true;
      to.setEffectiveTimeScale(1);
      to.setEffectiveWeight(1);
      from.crossFadeTo(to, 0.25, false);
    }
    if (this.walk && walking) this.walk.setEffectiveTimeScale(THREE.MathUtils.clamp(speed / this.walkSpeed, 0.6, 2.6));
    this.mixer.update(dt);
    this.placeHeld();
  }

  /** Carry this weapon (a copy, so the procedural rig keeps its own): in the right hand, or slung across the back. */
  hold(obj: THREE.Object3D | null, how: 'hand' | 'back'): void {
    if (this.held) this.root.remove(this.held);
    this.held = obj;
    this.heldHow = how;
    if (obj) {
      obj.matrixAutoUpdate = true;
      this.root.add(obj);
    }
  }

  /**
   * Put the carried weapon where the animated skeleton has the hand (pointing on
   * from the forearm, top to the front) or the upper back (diagonal, muzzle down
   * to the right).
   */
  private placeHeld(): void {
    const w = this.held;
    if (!w) return;
    this.root.updateMatrixWorld(true);
    const toLocal = this.root.getWorldQuaternion(this.q2).invert();
    if (this.heldHow === 'hand') {
      const fore = this.bones.get('R_Forearm');
      const hand = this.bones.get('R_Hand');
      if (!fore || !hand) return;
      fore.getWorldPosition(this.a);
      hand.getWorldPosition(this.b);
      const dir = this.a.subVectors(this.b, this.a).normalize();
      // weapons point along their local -y
      this.q.setFromUnitVectors(DOWN_Y, dir);
      w.position.copy(this.b.addScaledVector(dir, 0.05));
      this.root.worldToLocal(w.position);
      w.quaternion.copy(toLocal.multiply(this.q));
      return;
    }
    const spine = this.bones.get('Spine02') ?? this.bones.get('Spine01');
    if (!spine) return;
    spine.getWorldPosition(this.b);
    this.root.worldToLocal(this.b);
    // across the back: behind the spine (-z local, the player faces +z), muzzle up over the left shoulder
    w.position.set(this.b.x, this.b.y - 0.05, this.b.z - 0.2);
    w.quaternion.setFromEuler(BACK);
  }

  /** Which clip is playing (tests). */
  get state(): 'idle' | 'walk' {
    return this.walking ? 'walk' : 'idle';
  }
}
